import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const packageRoot = fileURLToPath(new URL('..', import.meta.url));
const outDir = join(packageRoot, 'src/icon/game');
const headerLines = [
  '// GENERATED by `pnpm --filter @bombfarm/ui icons:generate` — do not edit.',
  '// Source: packages/ui/icons/game/<basename>.svg',
];

for (const file of readdirSync(outDir).filter((name) => name.endsWith('.tsx'))) {
  const path = join(outDir, file);
  const source = readFileSync(path, 'utf8');
  const basename = file.replace(/\.tsx$/, '');
  const header = headerLines
    .map((line) => line.replace('<basename>', basename))
    .join('\n');

  if (source.startsWith(header)) {
    continue;
  }

  const withoutHeader = source.replace(
    /^\/\/ GENERATED by.*\n\/\/ Source:.*\n+/,
    '',
  );
  writeFileSync(path, `${header}\n${withoutHeader}`);
}
